res_prompt = primitives.call(name="observe_vima_prompt")
if res_prompt.ok:
    print("Prompt:", res_prompt.output)

res_inst = primitives.call(name="inspect_vima_instances", view="top")
if res_inst.ok:
    print("Instances:", res_inst.output)

res_scene = primitives.call(name="observe_vima_scene", include_raw=True, view="top")
if res_scene.ok:
    print("Scene keys:", list(res_scene.output.keys()))
    for k, v in res_scene.output.items():
        if k != "raw_observation":
            print(k, ":", v)
        else:
            print("raw_observation keys:", list(v.keys()))
            if "prompt_assets" in v:
                print("prompt_assets scene keys:", list(v["prompt_assets"]["scene"].keys()))
                print("obj_info:", v["prompt_assets"]["scene"]["obj_info"])

res_i5 = primitives.call(name="inspect_vima_instance", segmentation_id=5, view="top")
if res_i5.ok:
    print("Instance 5:", res_i5.output)

res_i6 = primitives.call(name="inspect_vima_instance", segmentation_id=6, view="top")
if res_i6.ok:
    print("Instance 6:", res_i6.output)

print("Scene output keys:", list(res_scene.output.keys()))
for k in res_scene.output:
    if k not in ["raw_observation", "rgb", "segm"]:
        print(k, res_scene.output[k])

if "raw_observation" in res_scene.output:
    raw = res_scene.output["raw_observation"]
    print("raw keys:", list(raw.keys()))
    for k in raw:
        if k not in ["rgb", "segm", "prompt_assets"]:
            print("raw", k, raw[k])
    if "prompt_assets" in raw:
        pa = raw["prompt_assets"]["scene"]
        print("pa keys:", list(pa.keys()))
        if "segm" in pa:
            print("pa segm keys:", list(pa["segm"].keys()))
            print("obj_info:", pa["segm"].get("obj_info"))
            top_seg = pa["segm"]["top"]
            # Find unique ids and centroids in prompt_assets top segm
            counts = {}
            sum_x = {}
            sum_y = {}
            for y in range(len(top_seg)):
                row = top_seg[y]
                for x in range(len(row)):
                    val = row[x]
                    counts[val] = counts.get(val, 0) + 1
                    sum_x[val] = sum_x.get(val, 0) + x
                    sum_y[val] = sum_y.get(val, 0) + y
            for val in counts:
                print(f"Prompt segm id {val}: count={counts[val]}, center=({sum_x[val]/counts[val]:.2f}, {sum_y[val]/counts[val]:.2f})")

print("Scene keys:", list(res_scene.output.keys()))
if "raw_observation" in res_scene.output:
    raw = res_scene.output["raw_observation"]
    print("raw keys:", list(raw.keys()))
    if "prompt_assets" in raw:
        pa = raw["prompt_assets"]["scene"]
        print("obj_info:", pa["segm"].get("obj_info"))
        top_seg = pa["segm"]["top"]
        counts = {}
        sum_x = {}
        sum_y = {}
        for y in range(len(top_seg)):
            row = top_seg[y]
            for x in range(len(row)):
                val = row[x]
                counts[val] = counts.get(val, 0) + 1
                sum_x[val] = sum_x.get(val, 0) + x
                sum_y[val] = sum_y.get(val, 0) + y
        for val in counts:
            print(f"Prompt segm id {val}: count={counts[val]}, center=({sum_x[val]/counts[val]:.2f}, {sum_y[val]/counts[val]:.2f})")

cand5 = primitives.call(name="build_vima_pick_place_action", source_segmentation_id=5, target_segmentation_id=6, view="top")
if cand5.ok:
    print("cand5:", cand5.output)

raw = res_scene.output["raw_scene"]
print("raw_scene keys:", list(raw.keys()))
if "prompt_assets" in raw:
    pa = raw["prompt_assets"]["scene"]
    print("pa keys:", list(pa.keys()))
    if "segm" in pa:
        print("obj_info:", pa["segm"].get("obj_info"))
        top_seg = pa["segm"]["top"]
        counts = {}
        sum_x = {}
        sum_y = {}
        min_x = {}
        max_x = {}
        min_y = {}
        max_y = {}
        for y in range(len(top_seg)):
            row = top_seg[y]
            for x in range(len(row)):
                val = row[x]
                counts[val] = counts.get(val, 0) + 1
                sum_x[val] = sum_x.get(val, 0) + x
                sum_y[val] = sum_y.get(val, 0) + y
                if val not in min_x or x < min_x[val]: min_x[val] = x
                if val not in max_x or x > max_x[val]: max_x[val] = x
                if val not in min_y or y < min_y[val]: min_y[val] = y
                if val not in max_y or y > max_y[val]: max_y[val] = y
        for val in counts:
            cx = (min_x[val] + max_x[val]) / 2.0
            cy = (min_y[val] + max_y[val]) / 2.0
            print(f"Prompt segm id {val}: count={counts[val]}, mean=({sum_x[val]/counts[val]:.2f}, {sum_y[val]/counts[val]:.2f}), bbox_center=({cx}, {cy}), bbox=[{min_x[val]}, {min_y[val]}, {max_x[val]}, {max_y[val]}]")
